"use client";
import { useEffect, useState, useRef } from "react";
import Image from "next/image";
import Link from "next/link";
import { prepareUpload } from "@/lib/prepare-upload";

interface Artwork {
  id: string; title: string; image: string; alt: string;
  medium?: string; artForm: string; category: string;
  description?: string; featured: boolean; published: boolean;
  sortOrder: number;
}

const ART_FORMS = [
  "Zendoodle art","Mandala art","Madhubani art","Water colour pencil art",
  "Kids colour pencil art","Fabric painting","Tanjore fabric painting",
  "Acrylic painting","Kerala mural painting","Poster painting",
  "Glass painting","Water colour painting","Pencil shading",
];

const BLANK: Omit<Artwork, "id"> = {
  title: "", image: "", alt: "", medium: "", artForm: ART_FORMS[0],
  category: "Painting", description: "", featured: false, published: true, sortOrder: 0,
};

const F = ({ label, children }: { label: string; children: React.ReactNode }) => (
  <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
    <label style={{ fontSize: "13px", fontWeight: 600, color: "rgba(32,36,59,.65)" }}>{label}</label>
    {children}
  </div>
);

export default function AdminArtworks() {
  const [artworks, setArtworks] = useState<Artwork[]>([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState<null | "add" | Artwork>(null);
  const [form, setForm] = useState<Omit<Artwork, "id">>(BLANK);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState("");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  const fetchArtworks = () => {
    setLoading(true);
    fetch("/api/admin/artworks").then(r => r.json()).then(d => { setArtworks(d); setLoading(false); });
  };

  useEffect(() => { fetchArtworks(); }, []);

  const showToast = (msg: string) => { setToast(msg); setTimeout(() => setToast(""), 3000); };

  const openAdd = () => { setForm({ ...BLANK, sortOrder: artworks.length + 1 }); setModal("add"); };
  const openEdit = (art: Artwork) => { setForm({ ...art }); setModal(art); };
  const closeModal = () => { setModal(null); };

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
    const fd = new FormData();
    fd.append("file", await prepareUpload(file));
    const res = await fetch("/api/admin/upload", { method: "POST", body: fd });
    const data = await res.json();
    if (data.url) setForm(f => ({ ...f, image: data.url }));
    else showToast("Upload failed: " + (data.error || "unknown error"));
    } catch (error) { showToast(error instanceof Error ? error.message : "Upload failed. Please retry."); }
    finally { setUploading(false); }
  };

  const handleSave = async () => {
    setSaving(true);
    if (modal === "add") {
      const res = await fetch("/api/admin/artworks", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) });
      if (res.ok) { showToast("Artwork added!"); fetchArtworks(); closeModal(); }
    } else if (modal && typeof modal === "object") {
      const res = await fetch(`/api/admin/artworks/${modal.id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) });
      if (res.ok) { showToast("Saved!"); fetchArtworks(); closeModal(); }
    }
    setSaving(false);
  };

  const handleDelete = async (id: string, title: string) => {
    if (!confirm(`Delete "${title}"? This cannot be undone.`)) return;
    await fetch(`/api/admin/artworks/${id}`, { method: "DELETE" });
    showToast("Deleted.");
    fetchArtworks();
  };

  const toggleField = async (id: string, field: "published" | "featured", val: boolean) => {
    await fetch(`/api/admin/artworks/${id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ [field]: val }) });
    fetchArtworks();
  };



  return (
    <div style={{ padding: "clamp(24px,4vw,40px)", position: "relative" }}>
      {/* Toast */}
      {toast && (
        <div style={{ position: "fixed", top: "20px", right: "20px", background: "#166534", color: "#fff", padding: "12px 20px", borderRadius: "12px", zIndex: 9999, fontSize: "14px", fontWeight: 500 }}>
          ✓ {toast}
        </div>
      )}

      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "28px", flexWrap: "wrap", gap: "12px" }}>
        <div>
          <h1 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "32px", fontWeight: 600, color: "var(--ink)", margin: "0 0 4px" }}>Artworks</h1>
          <p style={{ fontSize: "14px", color: "rgba(32,36,59,.5)", margin: 0 }}>{artworks.length} total artwork{artworks.length !== 1 ? "s" : ""}</p>
        </div>
        <button onClick={openAdd} className="btn-primary" style={{ fontSize: "14px", padding: "11px 22px" }}>+ Add Artwork</button>
      </div>

      {/* Table */}
      <div className="admin-card" style={{ padding: 0, overflow: "hidden" }}>
        {loading ? (
          <p style={{ padding: "40px", textAlign: "center", color: "rgba(32,36,59,.4)" }}>Loading…</p>
        ) : artworks.length === 0 ? (
          <div style={{ padding: "60px", textAlign: "center" }}>
            <p style={{ fontSize: "18px", color: "rgba(32,36,59,.4)", marginBottom: "16px" }}>No artworks yet</p>
            <button onClick={openAdd} className="btn-primary">Add First Artwork</button>
          </div>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <table className="admin-table">
              <thead><tr>
                <th>Image</th>
                <th>Title</th>
                <th>Art Form</th>
                <th>Published</th>
                <th>Featured</th>
                <th>Actions</th>
              </tr></thead>
              <tbody>
                {artworks.map(art => (
                  <tr key={art.id}>
                    <td>
                      {art.image ? (
                        <div style={{ width: "52px", height: "52px", borderRadius: "8px", overflow: "hidden", flexShrink: 0 }}>
                          <Image src={art.image} alt={art.title} width={52} height={52} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                        </div>
                      ) : <div style={{ width: "52px", height: "52px", borderRadius: "8px", background: "var(--canvas-alt)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "20px" }}>🖼</div>}
                    </td>
                    <td style={{ fontWeight: 600, maxWidth: "200px" }}>{art.title}</td>
                    <td style={{ color: "rgba(32,36,59,.6)", fontSize: "13px" }}>{art.artForm}</td>
                    <td>
                      <button
                        onClick={() => toggleField(art.id, "published", !art.published)}
                        style={{ background: "none", border: "none", cursor: "pointer", padding: 0 }}
                      >
                        <span className={art.published ? "badge-pub" : "badge-draft"}>{art.published ? "✓ Live" : "Draft"}</span>
                      </button>
                    </td>
                    <td>
                      <button
                        onClick={() => toggleField(art.id, "featured", !art.featured)}
                        style={{ background: "none", border: "none", cursor: "pointer", fontSize: "18px", padding: "4px" }}
                        title={art.featured ? "Remove from featured" : "Mark as featured"}
                      >
                        {art.featured ? "⭐" : "☆"}
                      </button>
                    </td>
                    <td>
                      <div style={{ display: "flex", gap: "8px" }}>
                        <button
                          onClick={() => openEdit(art)}
                          style={{ padding: "6px 14px", borderRadius: "8px", border: "1px solid var(--line)", background: "var(--canvas-alt)", cursor: "pointer", fontSize: "13px", fontWeight: 500 }}
                        >Edit</button>
                        <button
                          onClick={() => handleDelete(art.id, art.title)}
                          style={{ padding: "6px 12px", borderRadius: "8px", border: "1px solid rgba(220,60,60,.25)", background: "rgba(220,60,60,.07)", color: "#dc3c3c", cursor: "pointer", fontSize: "13px" }}
                        >Delete</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Modal */}
      {modal !== null && (
        <div onClick={closeModal} style={{ position: "fixed", inset: 0, background: "rgba(10,10,20,.7)", zIndex: 999, display: "flex", alignItems: "center", justifyContent: "center", padding: "16px" }}>
          <div onClick={e => e.stopPropagation()} style={{ background: "#fff", borderRadius: "24px", padding: "32px", width: "100%", maxWidth: "540px", maxHeight: "90vh", overflowY: "auto", display: "flex", flexDirection: "column", gap: "20px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <h2 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "24px", margin: 0 }}>{modal === "add" ? "Add Artwork" : "Edit Artwork"}</h2>
              <button onClick={closeModal} style={{ background: "none", border: "none", fontSize: "20px", cursor: "pointer", color: "rgba(32,36,59,.5)" }}>✕</button>
            </div>

            <F label="Title *">
              <input className="admin-input" value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} placeholder="e.g. Lotus Mandala" required />
            </F>

            <F label="Image">
              <div style={{ display: "flex", gap: "10px", alignItems: "flex-start" }}>
                <input className="admin-input" value={form.image} onChange={e => setForm(f => ({ ...f, image: e.target.value }))} placeholder="/images/artwork/..." style={{ flex: 1 }} />
                <button
                  type="button"
                  onClick={() => fileRef.current?.click()}
                  disabled={uploading}
                  style={{ padding: "10px 14px", borderRadius: "10px", border: "1.5px solid var(--line)", background: "var(--canvas-alt)", cursor: "pointer", fontSize: "13px", whiteSpace: "nowrap", fontFamily: "'DM Sans', sans-serif" }}
                >
                  {uploading ? "Uploading…" : "Upload"}
                </button>
                <input ref={fileRef} type="file" accept="image/*" onChange={handleUpload} style={{ display: "none" }} />
              </div>
              {form.image && (
                <div style={{ marginTop: "8px", width: "80px", height: "80px", borderRadius: "10px", overflow: "hidden" }}>
                  <Image src={form.image} alt="Preview" width={80} height={80} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                </div>
              )}
            </F>

            <F label="Alt text (for accessibility)">
              <input className="admin-input" value={form.alt} onChange={e => setForm(f => ({ ...f, alt: e.target.value }))} placeholder="Describe the artwork for screen readers" />
            </F>

            <F label="Art Form *">
              <select className="admin-input" value={form.artForm} onChange={e => setForm(f => ({ ...f, artForm: e.target.value }))}>
                {ART_FORMS.map(af => <option key={af}>{af}</option>)}
              </select>
            </F>

            <F label="Medium">
              <input className="admin-input" value={form.medium || ""} onChange={e => setForm(f => ({ ...f, medium: e.target.value }))} placeholder="e.g. Watercolour on paper" />
            </F>

            <F label="Description">
              <textarea className="admin-input" rows={3} value={form.description || ""} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} placeholder="Optional artwork description" style={{ resize: "vertical" }} />
            </F>

            <div style={{ display: "flex", gap: "24px" }}>
              <label style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "14px", fontWeight: 500, cursor: "pointer" }}>
                <input type="checkbox" checked={form.published} onChange={e => setForm(f => ({ ...f, published: e.target.checked }))} style={{ width: "16px", height: "16px" }} />
                Published (visible on site)
              </label>
              <label style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "14px", fontWeight: 500, cursor: "pointer" }}>
                <input type="checkbox" checked={form.featured} onChange={e => setForm(f => ({ ...f, featured: e.target.checked }))} style={{ width: "16px", height: "16px" }} />
                Featured
              </label>
            </div>

            <div style={{ display: "flex", gap: "12px", paddingTop: "8px" }}>
              <button onClick={handleSave} disabled={saving || !form.title} className="btn-primary" style={{ flex: 1, justifyContent: "center" }}>
                {saving ? "Saving…" : modal === "add" ? "Add Artwork" : "Save Changes"}
              </button>
              <button onClick={closeModal} className="btn-secondary" style={{ padding: "13px 20px" }}>Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import Image from "next/image";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useState } from "react";

const NAV = [
  { label: "Dashboard", href: "/admin", icon: "⊞" },
  { label: "Artworks", href: "/admin/artworks", icon: "🖼" },
  { label: "Workshops", href: "/admin/workshops", icon: "📅" },
  { label: "Settings", href: "/admin/settings", icon: "⚙" },
];

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const [loggingOut, setLoggingOut] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  const handleLogout = async () => {
    setLoggingOut(true);
    await fetch("/api/admin/auth/logout", { method: "POST" });
    router.push("/admin/login");
  };

  const Sidebar = () => (
    <aside className="admin-sidebar">
      {/* Logo */}
      <div style={{ padding: "24px 20px 16px", borderBottom: "1px solid rgba(255,249,242,.08)" }}>
        <div style={{ background: "rgba(255,249,242,.06)", borderRadius: "12px", padding: "10px 14px", display: "inline-flex", marginBottom: "8px" }}>
          <Image src="/images/logo/logo.png" alt="Kalavridhi Arts" width={110} height={50} style={{ objectFit: "contain", height: "40px", width: "auto" }} />
        </div>
        <p style={{ fontSize: "11px", color: "rgba(255,249,242,.35)", margin: 0, letterSpacing: "0.08em", textTransform: "uppercase" }}>
          Admin Panel
        </p>
      </div>

      {/* Nav links */}
      <nav style={{ flex: 1, padding: "12px 0", overflowY: "auto" }}>
        {NAV.map(item => (
          <Link
            key={item.href}
            href={item.href}
            className={`admin-nav-link${pathname === item.href ? " active" : ""}`}
            onClick={() => setMobileOpen(false)}
          >
            <span style={{ fontSize: "16px", width: "20px", textAlign: "center" }}>{item.icon}</span>
            {item.label}
          </Link>
        ))}

        <div style={{ margin: "8px 12px", height: "1px", background: "rgba(255,249,242,.08)" }} />

        <a
          href="/"
          target="_blank"
          rel="noopener noreferrer"
          className="admin-nav-link"
          style={{ fontSize: "13px" }}
        >
          <span style={{ fontSize: "14px", width: "20px", textAlign: "center" }}>↗</span>
          View Site
        </a>
      </nav>

      {/* Logout */}
      <div style={{ padding: "16px", borderTop: "1px solid rgba(255,249,242,.08)" }}>
        <button
          onClick={handleLogout}
          disabled={loggingOut}
          style={{
            width: "100%",
            padding: "10px 16px",
            background: "rgba(255,249,242,.07)",
            border: "1px solid rgba(255,249,242,.1)",
            borderRadius: "10px",
            color: "rgba(255,249,242,.6)",
            fontSize: "14px",
            cursor: "pointer",
            fontFamily: "'DM Sans', sans-serif",
            display: "flex",
            alignItems: "center",
            gap: "8px",
            transition: "background .2s",
          }}
          onMouseEnter={e => (e.currentTarget as HTMLElement).style.background = "rgba(220,60,60,.15)"}
          onMouseLeave={e => (e.currentTarget as HTMLElement).style.background = "rgba(255,249,242,.07)"}
        >
          <span>⏻</span>
          {loggingOut ? "Signing out…" : "Sign Out"}
        </button>
      </div>
    </aside>
  );

  return (
    <div style={{ display: "flex", minHeight: "100vh" }}>
      {/* Desktop sidebar */}
      <div className="admin-sidebar" style={{ display: "flex", flexDirection: "column" }}>
        <Sidebar />
      </div>

      {/* Mobile top bar */}
      <div style={{
        display: "none",
        position: "fixed",
        top: 0, left: 0, right: 0,
        height: "60px",
        background: "var(--ink)",
        borderBottom: "1px solid rgba(255,249,242,.08)",
        zIndex: 200,
        alignItems: "center",
        justifyContent: "space-between",
        padding: "0 16px",
      }} className="admin-mobile-bar">
        <Image src="/images/logo/logo.png" alt="Kalavridhi" width={90} height={40} style={{ objectFit: "contain", height: "36px", width: "auto" }} />
        <button
          onClick={() => setMobileOpen(m => !m)}
          style={{ background: "none", border: "none", color: "#fff", fontSize: "22px", cursor: "pointer" }}
        >
          {mobileOpen ? "✕" : "☰"}
        </button>
      </div>

      {/* Mobile sidebar overlay */}
      {mobileOpen && (
        <div
          onClick={() => setMobileOpen(false)}
          style={{
            position: "fixed", inset: 0, background: "rgba(0,0,0,.6)",
            zIndex: 198, display: "none",
          }}
          className="admin-mobile-overlay"
        />
      )}

      {/* Main content */}
      <div className="admin-main">
        {children}
      </div>

      <style>{`
        @media (max-width: 767px) {
          .admin-sidebar { display: none !important; }
          .admin-mobile-bar { display: flex !important; }
          .admin-main { margin-left: 0 !important; padding-top: 60px; }
        }
      `}</style>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import Link from "next/link";

interface StatsData {
  totalArtworks: number;
  publishedArtworks: number;
  totalWorkshops: number;
  publishedWorkshops: number;
  recentArtworks: Array<{ id: string; title: string; artForm: string; published: boolean; image?: string }>;
}

export default function AdminDashboard() {
  const [stats, setStats] = useState<StatsData | null>(null);

  useEffect(() => {
    Promise.all([
      fetch("/api/admin/artworks").then(r => r.json()),
      fetch("/api/admin/workshops").then(r => r.json()),
    ]).then(([artworks, workshops]) => {
      setStats({
        totalArtworks: artworks.length,
        publishedArtworks: artworks.filter((a: { published: boolean }) => a.published).length,
        totalWorkshops: workshops.length,
        publishedWorkshops: workshops.filter((w: { status: string }) => w.status === "published").length,
        recentArtworks: artworks.slice(-5).reverse(),
      });
    });
  }, []);

  const StatCard = ({ label, value, sub, color }: { label: string; value: number; sub: string; color: string }) => (
    <div className="admin-card" style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
      <p style={{ fontSize: "13px", color: "rgba(32,36,59,.5)", margin: 0, fontWeight: 600, letterSpacing: "0.05em", textTransform: "uppercase" }}>{label}</p>
      <p style={{ fontSize: "48px", fontFamily: "'Cormorant Garamond', serif", fontWeight: 700, margin: 0, color, lineHeight: 1 }}>{value ?? "—"}</p>
      <p style={{ fontSize: "13px", color: "rgba(32,36,59,.5)", margin: 0 }}>{sub}</p>
    </div>
  );

  return (
    <div style={{ padding: "clamp(24px,4vw,40px)" }}>
      {/* Header */}
      <div style={{ marginBottom: "32px" }}>
        <h1 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "36px", fontWeight: 600, color: "var(--ink)", margin: "0 0 6px" }}>
          Welcome back 🎨
        </h1>
        <p style={{ fontSize: "15px", color: "rgba(32,36,59,.55)", margin: 0 }}>
          Kalavridhi Arts — Content Management Dashboard
        </p>
      </div>

      {/* Stats */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px,1fr))", gap: "16px", marginBottom: "32px" }}>
        <StatCard label="Total Artworks" value={stats?.totalArtworks ?? 0} sub="in gallery" color="var(--maroon)" />
        <StatCard label="Published" value={stats?.publishedArtworks ?? 0} sub="visible on site" color="var(--leaf)" />
        <StatCard label="Workshops" value={stats?.totalWorkshops ?? 0} sub="total entries" color="var(--peacock)" />
        <StatCard label="Active" value={stats?.publishedWorkshops ?? 0} sub="published sessions" color="var(--saffron)" />
      </div>

      {/* Quick actions */}
      <div className="admin-card" style={{ marginBottom: "24px" }}>
        <h2 style={{ fontSize: "18px", fontWeight: 600, margin: "0 0 16px", color: "var(--ink)" }}>Quick Actions</h2>
        <div style={{ display: "flex", gap: "12px", flexWrap: "wrap" }}>
          {[
            { label: "Add Artwork", href: "/admin/artworks", emoji: "🖼" },
            { label: "Add Workshop", href: "/admin/workshops", emoji: "📅" },
            { label: "Edit Settings", href: "/admin/settings", emoji: "⚙" },
            { label: "View Public Site", href: "/", emoji: "↗" },
          ].map(a => (
            <Link
              key={a.href}
              href={a.href}
              target={a.href === "/" ? "_blank" : undefined}
              style={{
                display: "inline-flex", alignItems: "center", gap: "8px",
                padding: "10px 18px",
                background: "var(--canvas-alt)",
                border: "1px solid var(--line)",
                borderRadius: "10px",
                fontSize: "14px",
                fontWeight: 500,
                color: "var(--ink)",
                textDecoration: "none",
                transition: "background .2s, transform .15s",
              }}
              onMouseEnter={e => (e.currentTarget as HTMLElement).style.background = "rgba(129,46,72,.08)"}
              onMouseLeave={e => (e.currentTarget as HTMLElement).style.background = "var(--canvas-alt)"}
            >
              <span>{a.emoji}</span> {a.label}
            </Link>
          ))}
        </div>
      </div>

      {/* Recent artworks */}
      <div className="admin-card">
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
          <h2 style={{ fontSize: "18px", fontWeight: 600, margin: 0, color: "var(--ink)" }}>Recent Artworks</h2>
          <Link href="/admin/artworks" style={{ fontSize: "13px", color: "var(--maroon)", textDecoration: "none", fontWeight: 500 }}>
            View all →
          </Link>
        </div>
        {stats ? (
          <table className="admin-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Art Form</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {stats.recentArtworks.length === 0 ? (
                <tr><td colSpan={3} style={{ color: "rgba(32,36,59,.4)", textAlign: "center", padding: "24px" }}>No artworks yet. <Link href="/admin/artworks" style={{ color: "var(--maroon)" }}>Add one →</Link></td></tr>
              ) : (
                stats.recentArtworks.map(art => (
                  <tr key={art.id}>
                    <td style={{ fontWeight: 500 }}>{art.title}</td>
                    <td style={{ color: "rgba(32,36,59,.6)" }}>{art.artForm}</td>
                    <td><span className={art.published ? "badge-pub" : "badge-draft"}>{art.published ? "Published" : "Draft"}</span></td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        ) : (
          <p style={{ color: "rgba(32,36,59,.4)", textAlign: "center", padding: "24px 0" }}>Loading…</p>
        )}
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";

interface Settings {
  siteName: string; tagline: string; whatsapp: string; instagram: string;
  founderName: string; founderTitle: string; yearsExperience: string;
  shortBio: string; qualifications: string[];
  heroHeading: string; heroSubheading: string;
  enableEnquiryForm: boolean; metaDescription: string;
}

const F = ({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) => (
  <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
    <label style={{ fontSize: "13px", fontWeight: 600, color: "rgba(32,36,59,.65)" }}>{label}</label>
    {hint && <p style={{ fontSize: "12px", color: "rgba(32,36,59,.4)", margin: 0 }}>{hint}</p>}
    {children}
  </div>
);

export default function AdminSettings() {
  const [form, setForm] = useState<Settings | null>(null);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState("");
  const [newQual, setNewQual] = useState("");

  useEffect(() => {
    fetch("/api/admin/settings").then(r => r.json()).then(setForm);
  }, []);

  const showToast = (msg: string) => { setToast(msg); setTimeout(() => setToast(""), 3500); };

  const handleSave = async () => {
    if (!form) return;
    setSaving(true);
    const res = await fetch("/api/admin/settings", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });
    if (res.ok) showToast("Settings saved! Changes are live on the site.");
    else showToast("Error saving settings.");
    setSaving(false);
  };

  const addQual = () => {
    if (!newQual.trim() || !form) return;
    setForm(f => f ? ({ ...f, qualifications: [...f.qualifications, newQual.trim()] }) : f);
    setNewQual("");
  };
  const removeQual = (i: number) => {
    setForm(f => f ? ({ ...f, qualifications: f.qualifications.filter((_, idx) => idx !== i) }) : f);
  };

  if (!form) return <div style={{ padding: "40px", textAlign: "center", color: "rgba(32,36,59,.4)" }}>Loading settings…</div>;



  const Section = ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div className="admin-card" style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
      <h2 style={{ fontSize: "18px", fontWeight: 600, margin: 0, color: "var(--ink)", paddingBottom: "12px", borderBottom: "1px solid var(--line)" }}>{title}</h2>
      {children}
    </div>
  );

  return (
    <div style={{ padding: "clamp(24px,4vw,40px)", position: "relative", maxWidth: "760px" }}>
      {toast && (
        <div style={{ position: "fixed", top: "20px", right: "20px", background: "#166534", color: "#fff", padding: "12px 20px", borderRadius: "12px", zIndex: 9999, fontSize: "14px", fontWeight: 500, maxWidth: "340px" }}>
          ✓ {toast}
        </div>
      )}

      <div style={{ marginBottom: "28px" }}>
        <h1 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "32px", fontWeight: 600, color: "var(--ink)", margin: "0 0 4px" }}>Site Settings</h1>
        <p style={{ fontSize: "14px", color: "rgba(32,36,59,.5)", margin: 0 }}>Changes here update the live website immediately after saving.</p>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
        {/* Contact */}
        <Section title="🔗 Contact & Social">
          <F label="WhatsApp Number" hint="Include country code, no spaces or +. e.g. 918925626784">
            <input className="admin-input" value={form.whatsapp} onChange={e => setForm(f => ({ ...f!, whatsapp: e.target.value }))} placeholder="918925626784" />
          </F>
          <F label="Instagram URL">
            <input className="admin-input" value={form.instagram} onChange={e => setForm(f => ({ ...f!, instagram: e.target.value }))} placeholder="https://www.instagram.com/..." />
          </F>
        </Section>

        {/* Founder */}
        <Section title="👩‍🎨 Founder / About">
          <F label="Founder Name">
            <input className="admin-input" value={form.founderName} onChange={e => setForm(f => ({ ...f!, founderName: e.target.value }))} />
          </F>
          <F label="Founder Title">
            <input className="admin-input" value={form.founderTitle} onChange={e => setForm(f => ({ ...f!, founderTitle: e.target.value }))} placeholder="Artist & Art Educator" />
          </F>
          <F label="Years of Experience">
            <input className="admin-input" value={form.yearsExperience} onChange={e => setForm(f => ({ ...f!, yearsExperience: e.target.value }))} placeholder="20" style={{ maxWidth: "120px" }} />
          </F>
          <F label="Short Bio">
            <textarea className="admin-input" rows={4} value={form.shortBio} onChange={e => setForm(f => ({ ...f!, shortBio: e.target.value }))} style={{ resize: "vertical" }} />
          </F>
          <F label="Qualifications">
            <div style={{ display: "flex", flexWrap: "wrap", gap: "8px", marginBottom: "8px" }}>
              {form.qualifications.map((q, i) => (
                <span key={i} style={{ display: "inline-flex", alignItems: "center", gap: "6px", background: "var(--canvas-alt)", border: "1px solid var(--line)", borderRadius: "8px", padding: "5px 10px", fontSize: "13px" }}>
                  {q}
                  <button onClick={() => removeQual(i)} style={{ background: "none", border: "none", cursor: "pointer", color: "rgba(32,36,59,.4)", fontSize: "14px", padding: 0, lineHeight: 1 }}>✕</button>
                </span>
              ))}
            </div>
            <div style={{ display: "flex", gap: "8px" }}>
              <input className="admin-input" value={newQual} onChange={e => setNewQual(e.target.value)} onKeyDown={e => e.key === "Enter" && addQual()} placeholder="Add qualification…" style={{ flex: 1 }} />
              <button onClick={addQual} style={{ padding: "10px 16px", borderRadius: "10px", border: "1.5px solid var(--maroon)", color: "var(--maroon)", background: "transparent", cursor: "pointer", fontWeight: 600, fontFamily: "'DM Sans', sans-serif" }}>Add</button>
            </div>
          </F>
        </Section>

        {/* Hero */}
        <Section title="🏠 Hero Section">
          <F label="Hero Heading">
            <input className="admin-input" value={form.heroHeading} onChange={e => setForm(f => ({ ...f!, heroHeading: e.target.value }))} placeholder="Where Creativity Blooms." />
          </F>
          <F label="Hero Subheading">
            <textarea className="admin-input" rows={2} value={form.heroSubheading} onChange={e => setForm(f => ({ ...f!, heroSubheading: e.target.value }))} style={{ resize: "vertical" }} />
          </F>
        </Section>

        {/* SEO */}
        <Section title="🔍 SEO">
          <F label="Site Name">
            <input className="admin-input" value={form.siteName} onChange={e => setForm(f => ({ ...f!, siteName: e.target.value }))} />
          </F>
          <F label="Tagline">
            <input className="admin-input" value={form.tagline} onChange={e => setForm(f => ({ ...f!, tagline: e.target.value }))} placeholder="Grow Your Dream" />
          </F>
          <F label="Meta Description" hint="Appears in Google search results (recommended: 140–160 chars)">
            <textarea className="admin-input" rows={3} value={form.metaDescription} onChange={e => setForm(f => ({ ...f!, metaDescription: e.target.value }))} style={{ resize: "vertical" }} />
            <p style={{ fontSize: "12px", color: form.metaDescription.length > 160 ? "#dc3c3c" : "rgba(32,36,59,.4)", margin: 0, textAlign: "right" }}>{form.metaDescription.length} / 160</p>
          </F>
        </Section>

        {/* Features */}
        <Section title="⚙ Features">
          <label style={{ display: "flex", alignItems: "center", gap: "12px", cursor: "pointer" }}>
            <input
              type="checkbox"
              checked={form.enableEnquiryForm}
              onChange={e => setForm(f => ({ ...f!, enableEnquiryForm: e.target.checked }))}
              style={{ width: "18px", height: "18px" }}
            />
            <div>
              <p style={{ margin: 0, fontWeight: 600, fontSize: "14px" }}>Enable Enquiry Form</p>
              <p style={{ margin: 0, fontSize: "13px", color: "rgba(32,36,59,.5)" }}>Show the contact form in the Contact section (form submits to WhatsApp)</p>
            </div>
          </label>
        </Section>

        <button
          onClick={handleSave}
          disabled={saving}
          className="btn-primary"
          style={{ alignSelf: "flex-start", fontSize: "15px", padding: "14px 32px" }}
        >
          {saving ? "Saving…" : "Save All Settings"}
        </button>
      </div>
    </div>
  );
}

